          "diario('diario.electivo.soporte')"
        ]
      },
      {
        "texto": "opcion.electivo.qa",
        "tendencia": "jugador.responsabilidad / 3",
        "efectos": [
          "jugador.elegir_electivo('carrera.software.area.qa')",
          "diario('diario.electivo.qa')"
        ]
      },
      {
        "texto": "opcion.electivo.ciberseguridad",
        "tendencia": "jugador.inteligencia / 4 + (100 - jugador.amabilidad) / 6",
        "efectos": [
          "jugador.elegir_electivo('carrera.software.area.ciberseguridad')",
          "diario('diario.electivo.ciberseguridad')"
        ]
      },
      {
        "texto": "opcion.electivo.datos",
        "tendencia": "jugador.inteligencia / 3 + jugador.apertura / 5",
        "efectos": [
          "jugador.elegir_electivo('carrera.software.area.datos')",
          "diario('diario.electivo.datos')"
        ]
      }
